package net.civeira.phylax.feature.identity.tenantconfig.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.identity.tenantconfig.domain.TenantConfig;
import net.civeira.phylax.feature.identity.tenantconfig.domain.valueobject.DisplayNameVO;

class DisplayNameValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of display name of tenant config")
  void test_display_name_value_holder_assign_plain_value() {
    Object holder = new Object();
    DisplayNameValueHolder<Object> value = new DisplayNameValueHolder<>(holder);
    Assertions.assertSame(holder, value.displayName("one"), "Setters must return the holder");
    Assertions.assertTrue(value.getDisplayNameValue().isPresent(),
        "The plain value must be stored");
    Assertions.assertEquals("one", value.getDisplayName().orElse(null),
        "The plain value must be recovered");
    Assertions.assertSame(holder, value.displayNameNull(), "Setters must return the holder");
    Assertions.assertTrue(value.getDisplayNameValue().isPresent(),
        "A null value object must be stored");
    Assertions.assertFalse(value.getDisplayName().isPresent(),
        "A null value must not have content");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of display name of tenant config")
  void test_display_name_value_holder_assign_value_object() {
    Object holder = new Object();
    DisplayNameValueHolder<Object> value = new DisplayNameValueHolder<>(holder);
    DisplayNameVO vo = DisplayNameVO.from("one");
    Assertions.assertFalse(value.getDisplayNameValue().isPresent(), "A new holder must be empty");
    Assertions.assertSame(holder, value.displayName(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getDisplayNameValue().orElseThrow());
    Assertions.assertSame(holder, value.displayName(Optional.empty()));
    Assertions.assertFalse(value.getDisplayNameValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.displayName(Optional.of(vo)));
    Assertions.assertSame(vo, value.getDisplayNameValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of display name of tenant config against the original")
  void test_display_name_value_holder_read() {
    Object holder = new Object();
    DisplayNameValueHolder<Object> value = new DisplayNameValueHolder<>(holder);
    DisplayNameVO vo = DisplayNameVO.from("one");
    DisplayNameVO other = DisplayNameVO.from("one");
    TenantConfig original = Mockito.mock(TenantConfig.class);
    Mockito.when(original.getDisplayNameValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readDisplayName(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNotNull(value.readDisplayName(Optional.empty(), fails),
        "Without value and original a null value is returned");
    Assertions.assertTrue(fails.isEmpty(), "An optional value is never reported as missing");
    value.displayName(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readDisplayName(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readDisplayName(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of display name of tenant config")
  void test_display_name_value_holder_unset() {
    Object holder = new Object();
    DisplayNameValueHolder<Object> value = new DisplayNameValueHolder<>(holder);
    DisplayNameVO vo = DisplayNameVO.from("one");
    value.displayName(vo);
    Assertions.assertSame(holder, value.unsetDisplayNameIfMatches("displayName_other"));
    Assertions.assertTrue(value.getDisplayNameValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetDisplayNameIfMatches("displayName"));
    Assertions.assertFalse(value.getDisplayNameValue().isPresent(),
        "The field name must clear the value");
    value.displayName(vo);
    Assertions.assertSame(holder, value.unsetDisplayName());
    Assertions.assertFalse(value.getDisplayNameValue().isPresent(), "Unset must clear the value");
  }
}
